css:
:root {
  --bg-base: #0a0a0a;
  --bg-surface: #111111;
  --bg-card: #1f1f1f;
  --border: #2a2a2a;
  --text: #fafafa;
  --text-muted: #a1a1aa;
  --accent: #0ea5e9;
  --success: #22c55e;
  --danger: #ef4444;
  --warning: #f59e0b;

  /* Uma cor por fonte de receita — a mesma em pílula, gráfico e avatar. */
  --src-empresa: #0ea5e9;
  --src-impressionart: #8b5cf6;
  --src-moto: #f59e0b;
  --src-mos: #22c55e;

  --fonte: 'Manrope', sans-serif;
  --fonte-titulo: 'Sora', sans-serif;
  --fonte-mono: 'JetBrains Mono', monospace;
}

body { background: var(--bg-base); color: var(--text); font-family: var(--fonte); }

/* Número em tabela, card ou badge nunca "dança" ao atualizar. */
.bs-num { font-variant-numeric: tabular-nums; }

.bs-fontes {
  width: min(520px, 100%);
  padding: 20px; border: 1px solid var(--border); border-radius: 12px; background: var(--bg-surface);
}
.bs-fontes-titulo {
  margin-bottom: 16px;
  font-family: var(--fonte-titulo); font-size: 15px; font-weight: 600; color: var(--text);
}

/* Cada fatia é flex: percentual — o flex-grow divide na proporção certa e a
   soma fecha 100% sozinha, mesmo com arredondamento. */
.bs-fontes-barra { display: flex; height: 8px; margin-bottom: 14px; overflow: hidden; border-radius: 4px; }

.bs-fontes-lista { display: flex; flex-direction: column; gap: 8px; }
.bs-fontes-item { display: flex; align-items: center; gap: 10px; }
.bs-fontes-ponto { width: 8px; height: 8px; flex-shrink: 0; border-radius: 999px; }
.bs-fontes-nome { flex: 1; min-width: 0; font-size: 12px; color: var(--text); }
.bs-fontes-valor { font-family: var(--fonte-titulo); font-size: 13px; font-weight: 600; color: var(--text); }
/* Coluna fixa: sem ela, "7%" e "43%" desalinham e a leitura vertical se perde. */
.bs-fontes-pct { width: 34px; text-align: right; font-size: 11px; color: var(--text-muted); }
